const PXSubmit = (globalThis as any).PXSubmit;
const MAX_ATTEMPTS_PER_CASE = 30;
const CORS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};
const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { ...CORS, 'Content-Type': 'application/json' } });

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: CORS });
  if (req.method !== 'POST') return json({ error: 'method_not_allowed' }, 405);
  try {
    const db = createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!, {
      auth: { persistSession: false, autoRefreshToken: false },
    });

    // 1) Who is calling? (verified with Supabase Auth, not trusted from the body)
    const token = (req.headers.get('Authorization') || '').replace(/^Bearer\s+/i, '');
    const { data: auth, error: authErr } = await db.auth.getUser(token);
    const email = auth?.user?.email?.toLowerCase();
    if (authErr || !email) return json({ error: 'not_signed_in' }, 401);
    const { data: found } = await db.from('members').select('id, email').ilike('email', email.replace(/[\\%_]/g, '\\$&'));
    const member = (found || []).find((m: any) => (m.email || '').toLowerCase() === email);
    if (!member) return json({ error: 'not_a_member' }, 403);

    // 2) What did they play?
    let body: any;
    try { body = await req.json(); } catch { return json({ error: 'bad_request' }, 400); }
    const caseId = String(body?.caseId || '');
    const { data: row } = await db.from('pixel_cases').select('id, status, publish_at, close_at, data').eq('id', caseId).maybeSingle();
    if (!row) return json({ error: 'case_not_found' }, 404);

    const { data: mine } = await db.from('pixel_attempts').select('id, official, score').eq('case_id', caseId).eq('member_id', member.id);
    if ((mine || []).length >= MAX_ATTEMPTS_PER_CASE) return json({ error: 'too_many_attempts' }, 429);
    const prevOfficial = (mine || []).find((a: any) => a.official);

    // 3) Replay and score on the server
    const r = PXSubmit.evaluate({ caseRow: row, history: body?.history, now: new Date(), hasOfficial: !!prevOfficial });
    if (!r.ok) return json({ error: r.error, detail: r.detail }, r.status);

    const rec = { ...r.record, member_id: member.id };
    let { error: insErr } = await db.from('pixel_attempts').insert(rec);
    if (insErr && insErr.code === '23505') { rec.official = false; ({ error: insErr } = await db.from('pixel_attempts').insert(rec)); }
    if (insErr) return json({ error: 'save_failed', detail: insErr.message }, 500);

    // 4) Rank among official attempts
    const { data: board } = await db.from('pixel_attempts').select('member_id, score, sim_minutes, created_at').eq('case_id', caseId).eq('official', true);
    const rank = PXSubmit.rankOf(board || [], member.id);
    return json({
      ok: true, official: rec.official, live: r.live, score: rec.score, xp: rec.xp, ending: rec.ending,
      officialScore: rec.official ? rec.score : (prevOfficial ? prevOfficial.score : null),
      rank: rank.rank, of: rank.of,
    });
  } catch (e) {
    return json({ error: 'server_error', detail: String(e?.message || e) }, 500);
  }
});
